const patternTranslations = [
  { pattern: /^(\d+) Plans$/, translate: ([, count], dictionary) => dictionary.plans(count) },
  { pattern: /^(\d+) active$/, translate: ([, count], dictionary) => dictionary.active(count) },
  { pattern: /^Verified (.+)$/, translate: ([, date], dictionary) => dictionary.verified(date) },
  { pattern: /^Maining (\d+)$/, translate: ([, number], dictionary) => dictionary.maining(number) },
  { pattern: /^Maining Plan (\d+)$/, translate: ([, number], dictionary) => dictionary.mainingPlan(number) },
  { pattern: /^Buy Maining Plan (\d+)$/, translate: ([, number], dictionary) => dictionary.buyMainingPlan(number) },
  { pattern: /^Daily (.+) - 17 day (.+)$/, translate: ([, daily, profit], dictionary) => dictionary.dailyPeriod(daily, profit) },
  { pattern: /^Daily (.+)$/, translate: ([, amount], dictionary) => dictionary.daily(amount) },
  { pattern: /^(.+) left$/, translate: ([, time], dictionary) => dictionary.left(time) },
  { pattern: /^Task (.+) \/ Deposit (.+)$/, translate: ([, task, deposit], dictionary) => dictionary.taskDeposit(task, deposit) },
  { pattern: /^Team (\d+)$/, translate: ([, number], dictionary) => dictionary.team(number) },
  { pattern: /^(.+) is selected for this browser\.$/, translate: ([, language], dictionary, languageId) => dictionary.selected(translatePhrase(language, languageId)) },
  { pattern: /^(.+) was added to your profile\.$/, translate: ([, plan], dictionary) => dictionary.added(plan) },
  { pattern: /^Wallet credited with (.+)\.$/, translate: ([, amount], dictionary) => dictionary.credited(amount) },
  { pattern: /^Withdrawal submitted\. You receive (.+) after (.+) fee\.$/, translate: ([, receive, fee], dictionary) => dictionary.withdrawal(receive, fee) },
  { pattern: /^Invite code: (.+)$/, translate: ([, code], dictionary) => dictionary.inviteCode(code) },
  { pattern: /^(.+) from wallet (.+)$/, translate: ([, amount, wallet], dictionary) => dictionary.walletFrom(amount, wallet) },
  { pattern: /^Registered by (.+)$/, translate: ([, name], dictionary) => dictionary.registeredBy(name) },
  { pattern: /^Paid with (.+)$/, translate: ([, crypto], dictionary) => dictionary.paidWith(crypto) },
]
